const u=[{id:"meaning-frankl",title:"M17 · Viktor Frankl Institute of America · Sinn aus Sicht der Logotherapie",url:"https://viktorfranklamerica.com/meaning-from-a-logotherapy-perspective/",type:"guidance",finding:"Frankl beschrieb Sinn durch Schaffen oder Handeln, Erleben oder Lieben und eine frei gewählte Haltung zu unvermeidbarem Leid.",limitation:"Ein philosophischer und klinischer Ansatz, keine Studie. Leid ist keine Voraussetzung. Diese Reflexion belegt keine Wirkung als Behandlung."},{id:"meaning-frankl-history",title:"M18 · Viktor Frankl Institut Wien · Biografie",url:"https://www.viktorfrankl.org/biography.html",type:"guidance",finding:"Frankl entwickelte die Logotherapie schon vor seiner Haft unter dem NS-Regime. Die Biografie des Instituts beschreibt sein Leben und Werk.",limitation:"Historische Erfahrungen belegen nicht die Wirksamkeit einer psychologischen Intervention. Sie verpflichten dich auch nicht, im Leid einen Sinn zu finden."},{id:"meaning-act-values",title:"M19 · Association for Contextual Behavioral Science · Die sechs Kernprozesse der ACT",url:"https://contextualscience.org/six_core_processes_act",type:"guidance",finding:"In der ACT beschreiben Werte, wie du auf Dauer handeln möchtest. Engagiertes Handeln verbindet sie mit konkreten Zielen.",limitation:"Eine fachliche Beschreibung des Modells, kein Experiment. ODAs Kompass und kurze Schritte sind Anpassungen ohne validierte Bewertung oder nachgewiesene Einzelwirkung."},{id:"meaning-act-trials",title:"M04 · A-Tjak und andere · 2015 · Metaanalyse zur ACT",url:"https://doi.org/10.1159/000365764",type:"research",finding:"39 randomisierte Studien mit 1.821 Menschen prüften vollständige ACT-Behandlungen bei klinisch relevanten psychischen oder körperlichen Problemen.",limitation:"Die Befunde zu vollständigen Behandlungen zeigen nicht die Wirkung von Werte-Arbeitsblättern allein. Sie bestätigen weder diesen Kurs noch eine Überlegenheit gegenüber etablierter kognitiver Verhaltenstherapie."},{id:"meaning-sdt",title:"M05 · Ryan und Deci · 2000 · Selbstbestimmungstheorie",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"Die Theorie unterscheidet selbst befürwortete Motivation von Druck. Auch zunächst von außen übernommene Aufgaben können persönlich wichtig werden.",limitation:"Ein Theorieartikel, kein Test deiner Beweggründe. Schuldgefühle, Freude, körperliche Energie oder Aufmerksamkeit anderer zeigen nicht, ob ein Wert wirklich deiner ist."},{id:"meaning-sdt-interventions",title:"M06 · Ntoumanis und andere · 2021 · Programme zur Gesundheitsmotivation",url:"https://eprints.whiterose.ac.uk/id/eprint/155741/",type:"research",finding:"73 Studien zu Gesundheitsprogrammen mit 30.088 Teilnehmenden fanden im Durchschnitt Verbesserungen bei selbstbestimmter Motivation und Gesundheitsverhalten. Die Effekte unterschieden sich.",limitation:"58 randomisierte und 15 quasi-experimentelle Studien prüften verschiedene begleitete Programme. Ein kurzes Werte-Arbeitsblatt entspricht nicht den untersuchten Maßnahmen."},{id:"meaning-support",title:"M20 · National Institute of Mental Health · Depression",url:"https://www.nimh.nih.gov/health/publications/depression",type:"guidance",finding:"Anhaltende Niedergeschlagenheit, Hoffnungslosigkeit, Interessenverlust oder Schwierigkeiten im Alltag verdienen fachliche Abklärung und Unterstützung. In den USA gibt es Krisenhilfe unter 988.",limitation:"Fehlender Sinn allein ist keine Diagnose einer Depression. ODA bietet Lernhilfe und kann weder Depressionen behandeln noch akute Krisen bewältigen."},{id:"meaning-carrillo",title:"M09 · Carrillo und andere · 2019 · Metaanalyse zur Übung „Best Possible Self“",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"29 Studien mit 2.909 Teilnehmenden stützten durchschnittliche Verbesserungen bei Wohlbefinden, positiven Gefühlen und Optimismus. Eine Abnahme negativer Gefühle oder von Depression wurde nicht nachgewiesen.",limitation:"Beide Konfidenzintervalle zu Symptomen schlossen null ein. Nur drei Studien erfassten Depression. Meist kurze Untersuchungen mit verschiedenen Abläufen. Mehr Sinn oder spätere Erfolge wurden nicht nachgewiesen."},{id:"meaning-best-possible-self",title:"M10 · King · 2001 · Über Lebensziele schreiben",url:"https://doi.org/10.1177/0146167201277003",type:"research",finding:"81 Studierende wurden zufällig vier Schreibbedingungen zugeordnet. Die Zukunftsübung sah an vier aufeinanderfolgenden Tagen jeweils 20 Minuten Schreiben vor.",limitation:"Die ursprüngliche Aufgabe prüfte nicht diese kurze ODA-Anpassung mit Wertebezug. Sie belegte weder mehr Sinn noch Krankheitsvorbeugung oder tatsächlich erreichte Zukunftsziele."},{id:"meaning-planning",title:"M11 · Gollwitzer und Sheeran · 2006 · Wenn-dann-Pläne",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 unabhängige Untersuchungen mit 8.461 Teilnehmenden stützten durchschnittliche Vorteile beim Erreichen von Zielen, wenn Pläne eine konkrete Situation mit einer beabsichtigten Reaktion verbanden.",limitation:"Die Auswertung umfasste Experimente und Korrelationsstudien in unterschiedlichen Situationen. Planen ist kein Handeln. Mehr Sinn oder dieser kombinierte ODA-Ablauf wurden nicht nachgewiesen."},{id:"meaning-mental-contrasting",title:"M13 · Wang, Wang und Gai · 2021 · Mentales Kontrastieren und Planen",url:"https://www.frontiersin.org/articles/10.3389/fpsyg.2021.565202/pdf",type:"research",finding:"24 unabhängige Studien aus 21 Artikeln mit 15.907 Teilnehmenden fanden einen mäßigen durchschnittlichen Effekt auf die Zielerreichung: g = 0,336 [0,229; 0,443].",limitation:"Publikationsverzerrungen und verschiedene Formate begrenzen die Genauigkeit. Die Kombination aus Werten, Zukunftsszene und Handeln wurde nicht geprüft. Strukturelle Hindernisse sind kein persönliches Versagen."},{id:"meaning-monitoring",title:"M14 · Harkin und andere · 2016 · Fortschritte beobachten",url:"https://eprints.whiterose.ac.uk/id/eprint/87431/1/bul%20harkin%20raw%20final.pdf",type:"research",finding:"138 randomisierte Studien fanden im Durchschnitt Vorteile beim Erreichen von Zielen, wenn Fortschritte häufiger beobachtet wurden: d = 0,40 [0,32; 0,48].",limitation:"Bei kleinen Studien zeigte sich eine Asymmetrie. Eine Sensitivitätsanalyse schätzte d = 0,19. Unterschiedliche Ziele und Methoden bestätigen weder ODAs Rückblick am Folgetag noch Sinneffekte oder verpflichtendes öffentliches Protokollieren."},{id:"meaning-habits",title:"M15 · Lally und andere · 2010 · Gewohnheiten entwickeln",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"Eine 84-tägige Beobachtungsstudie begleitete 96 Teilnehmende. Im Modell entwickelte sich automatisches Handeln unterschiedlich schnell. Eine verpasste Gelegenheit hatte wenig messbaren Einfluss.",limitation:"Der oft genannte Median von 66 Tagen und die Spanne von 18–254 Tagen sind Modellschätzungen. Längere Werte wurden hochgerechnet. Sie sind weder Fristen noch Belege für wiederholte Ausfälle oder automatisch werdende Werte."}],h=[{schemaVersion:2,revision:2,id:"meaning-1",courseId:"meaning",locale:"de",title:"Die Woche war voll. Was war dir wichtig?",goal:"Tu heute etwas Nützliches für eine gewählte Beziehung oder einen Beitrag.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Wieder nur Arbeit, Haushalt und Scrollen? Gib einer Sache, die dir wichtig ist, heute wirklich Platz.",reason:{id:"meaning-1-reason-attention-cost",label:"Welche verzichtbare Tätigkeit könntest du verschieben, um dafür zwei Minuten zu haben?",kind:"text",maxLength:160,optional:!0,suggestions:["Scrollen auf später verschieben","Eine nicht dringende Hausarbeit verschieben","Kurz Zeit füreinander schaffen"]},why:{id:"meaning-1-why",label:"Was ist dir diese Woche wichtig genug, dass du ihm Aufmerksamkeit schenken möchtest?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Du brauchst keine große Lebensaufgabe, bevor du etwas tust, das dir wichtig ist. Frankls Philosophie nennt mehrere mögliche Wege: Schaffen oder Handeln, Erleben oder Lieben und eine Haltung zu unvermeidbarem Leid. Das sind Denkanstöße, kein Test und keine nachgewiesene Behandlung. Mit Leid musst du dich hier nicht beschäftigen.","Wähle für deinen Versuch im Lauf dieses Kurses eine Beziehung oder einen Beitrag. Tu etwas Kleines bei einer passenden Gelegenheit und halte danach fest, was passiert ist. Eine Frage stellen und zuhören ist Handeln. Wichtige Menschen auflisten ist Vorbereitung. Deine Stimmung muss sich nicht ändern. Schau auf das, was du tatsächlich tust."],example:{title:"Thomas fragt beim Abendessen nach",text:"Beim Abendessen am Dienstag merkt Thomas, dass er seiner Tochter diese Woche kaum zugehört hat. Er legt sein Handy weg, fragt nach ihrem Biologieprojekt und hört zu. Sie antwortet mit zwei kurzen Sätzen, bevor sie losmuss. Er notiert, dass er gefragt und aufmerksam zugehört hat. Das Gespräch war kurz, aber es fand statt."}},move:{invitation:"Tu etwas Nützliches für die Beziehung oder den Beitrag, den du gewählt hast.",instructions:["Wähle eine Richtung, die du im Kurs beibehalten willst.","Tu etwas Kleines und halte danach fest, was passiert ist."],prompts:[],suggestions:{action:["Fragen und zuhören, Handy weg","Einen nützlichen Satz fürs Projekt schreiben","Eine konkrete Hilfe anbieten"],minimum:["Eine Frage stellen und zuhören","Einen brauchbaren Satz schreiben","Ein konkretes Angebot machen"],cue:["Wenn wir nach dem Abendessen zusammensitzen","Wenn ich mein Projekt öffne","Beim nächsten sicheren Austausch"],place:["Am Küchentisch","An meinem gewohnten Arbeitsplatz","In einem sicheren Nachrichtenverlauf"],minutes:[2,5],fallback:["Eine sichere Sprach- oder Textnachricht nutzen","Eine andere passende Gelegenheit wählen","Um praktische Unterstützung bitten"],observation:["Was ich gefragt und gehört habe","Der brauchbare Satz, den ich geschrieben habe","Ob ich mein Angebot gemacht habe"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Fragen und zuhören, Handy weg",minimum:"Eine Frage stellen und zuhören",minutes:2,cueHint:"Wenn wir nach dem Abendessen zusammensitzen",placeHint:"Am Küchentisch",obstacleHint:"Die Person hat keine Zeit oder ich bin abgelenkt.",fallbackHint:"Eine sichere Sprach- oder Textnachricht nutzen",observationHint:"Was ich gefragt und gehört habe"},stopRule:"Wähle einen sicheren Kontakt, den beide möchten. Hilfe muss zu deinen Möglichkeiten und Grenzen passen.",accessibleAlternative:"Nutze deine gewohnte Art zu kommunizieren, einen Beitrag mit Unterstützung oder etwas Kreatives für dich allein."},result:{question:"Hast du deinen gewählten Schritt getan?",observationPrompt:"Was hast du beigetragen, gefragt oder gehört?"},judgment:{primary:{id:"meaning-1-dinner-opening-decision",scenario:"Thomas möchte heute Abend vom Projekt seiner Tochter hören. Sie hat fünf Minuten, bevor sie losmuss. Der Abwasch kann warten. Er möchte auch eine hilfreiche Frage vorbereiten.",question:"Wie nutzt er diese Gelegenheit für das, was er gewählt hat?",options:[{id:"listen-now",text:"Jetzt nach dem Projekt fragen und zuhören. Danach festhalten, was tatsächlich passiert ist.",feedback:"So nutzt er die Gelegenheit für das aufmerksame Gespräch, das er gewählt hat. Die Antwort kann kurz oder zerstreut sein. Abwasch und weitere Vorbereitung können warten. Nähe muss deshalb nicht für alle Vorrang haben."},{id:"meaning-1-share-chore",text:"In den fünf Minuten gemeinsam abwaschen und beim Abräumen nach dem Projekt fragen.",feedback:"Gemeinsame Hausarbeit kann Nähe schaffen. Hier hat Thomas aber aufmerksames Zuhören gewählt und der Abwasch kann warten. Halte das kurze Gespräch frei, statt die Aufmerksamkeit zu teilen. Außer beide möchten lieber gemeinsam abräumen."},{id:"meaning-1-prepare-question",text:"Die fünf Minuten für eine durchdachte Projektfrage nutzen und sie nach ihrem Aufbruch schicken.",feedback:"Eine vorbereitete Frage kann ein späteres Gespräch erleichtern. Hier hat sie Zeit und er kennt das Thema schon. Jetzt fragen. Möchte sie nicht reden, wird „Keine Gelegenheit“ festgehalten."}],bestOptionId:"listen-now"}},carry:{takeaway:"Gib dem, was dir wichtig ist, Platz. Halte danach die Tatsachen fest.",followUp:{questionId:"meaning-1-return",question:"Was ist passiert, als deine gewählte Gelegenheit kam?",observationPrompt:"Was hast du getan? War die Gelegenheit tatsächlich da?",adjustmentPrompt:"Was würdest du für die nächste Gelegenheit verschieben oder ändern?"}},goDeeper:{sections:[{heading:"Eine Philosophie mit mehreren Wegen",paragraphs:["Frankls drei Wege stammen aus einem philosophischen und klinischen Ansatz. Sie sind keine Checkliste, die alle abarbeiten müssen. Schaffen kann nützliche Arbeit oder eine Tat sein. Erleben kann heißen, Schönheit wahrzunehmen oder einer Beziehung Aufmerksamkeit zu schenken. Auch eine Haltung zu unvermeidbarem Leid ist möglich, aber niemals Pflicht. Du kannst einen Beitrag oder eine Beziehung wählen, ohne Schmerz zu beschreiben. Das Viktor Frankl Institute of America stellt diese Wege vor [M17].","Die Biografie des Wiener Instituts zeigt, dass Frankl die Logotherapie bereits vor seiner Haft unter dem NS-Regime entwickelte [M18]. Seine späteren Erfahrungen gehören zu seiner Geschichte. Sie belegen nicht, dass eine kurze Lektion Belastungen behandelt. Dieser Kurs greift Fragen aus der Philosophie auf. Die Antworten bleiben bei dir. Auch ohne große Antwort kannst du einen kleinen Schritt wählen. Eine aufmerksame Frage, ein nützlicher Absatz oder ein begrenztes Hilfsangebot macht sichtbar, was du für deine Richtung getan hast."]},{heading:"Vom Wahrnehmen zur passenden Gelegenheit",paragraphs:["Ein Plan, der sinnvoll klingt, und ein erledigter Schritt sind verschiedene Dinge. Die Planungsforschung stützt, eine Gelegenheit mit einer Reaktion zu verbinden: Wenn eine erkennbare Situation eintritt, tust du das, was du beabsichtigst. Gollwitzer und Sheeran werteten 94 unabhängige Untersuchungen mit 8.461 Teilnehmenden aus [M11]. Im Durchschnitt wurden Ziele besser erreicht. Menschen, Ziele und Studiendesigns unterschieden sich aber. Das belegt weder mehr Sinn durch Planung noch die Wirksamkeit dieser Kombination aus Philosophie und Handeln in ODA.","In ODAs Anpassung wählst du eine Richtung, einen Schritt und ein machbares Minimum. Der erste Schritt muss dazu passen: Einer Antwort zuhören dient der Beziehung. Nur die Kontaktliste zu öffnen ist Vorbereitung. Gab es keine Gelegenheit, halte das so fest. Ein künftiger Termin bleibt geplant. Du musst nicht beweisen, dass das Gespräch dein Leben verändert hat. Praktisch liefert es Hinweise für deine nächste Wahl. Vielleicht passen ein anderes Umfeld, Unterstützung oder eine andere Richtung besser zu dir."]}],sourceIds:["meaning-frankl","meaning-frankl-history","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-2",courseId:"meaning",locale:"de",title:"Für das Wichtige bleiben nur ein paar Minuten?",goal:"Halte Zeit für einen kleinen Schritt in deiner gewählten Richtung frei. Benenne, was dafür warten muss.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Du sagst, es ist dir wichtig. Bekommt es Zeit oder nur den Rest, wenn alles andere erledigt ist?",reason:{id:"meaning-2-reason",label:"Was verschiebst du, damit diese Richtung Zeit bekommt?",kind:"text",maxLength:160,optional:!0,suggestions:["Scrollen auf später verschieben","Mir weniger auf einmal vornehmen","Platz für sorgfältige Arbeit schaffen"]},why:{id:"meaning-2-why",label:"Was verschiebst du, damit diese Richtung Zeit bekommt?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ein Ziel kannst du abschließen, etwa jemanden am Sonntag besuchen. Ein Wert beschreibt, wie du auf Dauer handeln möchtest, etwa aufmerksam sein. Diese Unterscheidung stammt aus einem Therapiemodell. Sie besagt nicht, dass Ziele weniger wichtig sind. Ein verfehltes Ziel entscheidet auch nicht darüber, welche Richtung du einschlagen willst.","Bleib bei der Richtung und dem Schritt deines Versuchs. Schau auf das nächste freie Zeitfenster. Vielleicht konkurrieren zwei wertvolle Dinge darum. Wähle ein nützliches Minimum und sag, was warten wird. Das ist ein echter Verzicht für diesen Moment. Der andere Wert verschwindet dadurch nicht. Setze den Schritt um, bevor du deine Wahl bewertest."],example:{title:"Thomas schafft Platz",text:"Am Mittwoch hat Thomas zehn Minuten, bevor eine Hausarbeit ansteht. Er möchte wieder reden und außerdem lesen. Zwei Minuten widmet er dem Projekt seiner Tochter, dann beginnt er mit der Hausarbeit. Lesen wartet bis Donnerstag. Seine Tochter wirkt abgelenkt. Auch das hält er fest. Er hat einen begrenzten Schritt gewählt, statt alles hineinzupacken."}},move:{invitation:"Bleib bei deiner Richtung. Gib dem nächsten Schritt ein machbares Zeitfenster.",instructions:["Benenne etwas anderes, das diese Zeit ebenfalls beansprucht.","Wähle einen kleinen, nützlichen Schritt und setze ihn um."],prompts:[],suggestions:{action:["In der freigehaltenen Zeit fragen und zuhören","Einen nützlichen Satz fürs Projekt schreiben","Eine begrenzte Betreuungsaufgabe erledigen"],minimum:["Einer Antwort zuhören","Einen brauchbaren Satz verfassen","Eine kleine vereinbarte Aufgabe erledigen"],cue:["Wenn wir nach dem Abendessen zusammensitzen","In meiner freigehaltenen Projektzeit","Nach einer gewohnten Betreuungsaufgabe"],place:["Am Küchentisch","An meinem gewohnten Arbeitsplatz","Dort, wo die Aufgabe anfällt"],minutes:[2,5],fallback:["Ein kürzeres mögliches Gespräch führen","Die nützliche Aufgabe kleiner machen","Um Aufteilung der Verantwortung bitten"],observation:["Was ich getan habe und was wartete","Die tatsächlich genutzte Zeit","Ob die kleinere Fassung meiner Richtung diente"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"In der freigehaltenen Zeit fragen und zuhören",minimum:"Einer Antwort zuhören",minutes:2,cueHint:"Wenn wir nach dem Abendessen zusammensitzen",placeHint:"Am Küchentisch",obstacleHint:"Zwei wichtige Vorhaben beanspruchen dasselbe Zeitfenster.",fallbackHint:"Ein kürzeres mögliches Gespräch führen",observationHint:"Was ich getan habe und was wartete"},stopRule:"Verdränge weder dringende Versorgung noch nötige Erholung. Ändere stattdessen Zeitpunkt oder Umfang.",accessibleAlternative:"Nutze unterstützte Kommunikation, eine Aufgabe im Sitzen oder Hilfe, um deiner Richtung treu zu bleiben."},result:{question:"Hast du deinen kleinsten sinnvollen Schritt in der freigehaltenen Zeit umgesetzt?",observationPrompt:"Was hast du getan? Was musste warten?"},judgment:{primary:{id:"meaning-2-chosen-commitment-decision",scenario:"Thomas hat seiner Tochter vor ihrer Reise ein aufmerksames Gespräch versprochen. Die zehn Minuten heute Abend sind die letzte Gelegenheit. Auch ein nicht dringendes Lesekapitel ist ihm wichtig. Ein längeres Telefonat kann bis nächste Woche warten.",question:"Mit welcher Wahl hält er sein Versprechen in dieser Zeit?",options:[{id:"reading-later",text:"Jetzt kurz zuhören und fürs Lesen eine andere Zeit wählen. Dabei die begrenzte Zeit akzeptieren.",feedback:"So führt er das gewählte Gespräch, solange die Gelegenheit heute da ist. Lesen bleibt wichtig und kann eine andere Zeit bekommen. Hier zählen sein Versprechen und der Zeitpunkt, keine Rangfolge seiner Werte."},{id:"full-both",text:"Während des Zuhörens das Kapitel fertig lesen, damit keines der beiden wichtigen Vorhaben warten muss.",feedback:"Aufgaben zu verbinden kann Lesezeit retten. Hier teilt es aber die versprochene Aufmerksamkeit. Jetzt kurz zuhören und das Lesen verschieben, statt so zu tun, als passten beide Vorhaben vollständig hinein."},{id:"meaning-2-next-week-call",text:"Heute lesen und nächste Woche ein längeres Gespräch planen, damit beide Vorhaben ihre eigene feste Zeit haben.",feedback:"Getrennte Zeiten können sinnvoll sein. Auch ein längeres Telefonat kann sich lohnen. Das gewählte Gespräch vor der Reise entfällt dadurch trotzdem. Halte jetzt das kleine Versprechen. Plane einen längeren Austausch zusätzlich."}],bestOptionId:"reading-later"}},carry:{takeaway:"Ziel verfehlt? Behalte deine Richtung und setze heute einen machbaren Schritt um.",followUp:{questionId:"meaning-2-return",question:"Hat deine freigehaltene Zeit der gewählten Richtung gedient?",observationPrompt:"Diente das Minimum deiner Richtung? Was musste dafür warten?",adjustmentPrompt:"Bleibt es bei diesem Verzicht oder änderst du Zeit oder Umfang?"}},goDeeper:{sections:[{heading:"Richtung und Ziel erfüllen verschiedene Aufgaben",paragraphs:["Die Association for Contextual Behavioral Science beschreibt Werte als bewusst gewählte Arten, auf Dauer zu handeln. Engagiertes Handeln verbindet sie mit konkreten Zielen [M19]. Aufmerksam sein ist eine Richtung. Heute Abend einer Antwort zuhören ist ein begrenzter Schritt. Beides gehört zusammen. Du kannst den Schritt abschließen, ohne mit Aufmerksamkeit „fertig“ zu sein. Und du kannst ein Ziel ändern, während die Richtung bleibt. Das sind Unterscheidungen innerhalb des ACT-Modells, keine experimentell entdeckten Kategorien, die überall gelten.","ODAs Kompass ist eine Lernhilfe: Wähle einen Lebensbereich, benenne, wie du darin handeln willst, berücksichtige deine Umstände und wähle einen machbaren Schritt. Er hat keinen wissenschaftlich bestätigten Grenzwert. Du musst weder jeden Bereich bewerten noch die größte Zahlenlücke schließen. Wer Menschen betreut, wenig Energie hat oder feste Schichten arbeitet, kann zuerst darauf achten, was auf Dauer machbar ist. Entscheide anhand deiner wirklichen Woche, was Platz bekommt. Der Kompass fällt kein Urteil über dein Leben."]},{heading:"Ein kurzer Schritt ist keine vollständige Therapie",paragraphs:["A-Tjak und andere werteten 39 randomisierte Studien mit 1.821 Teilnehmenden aus, die klinisch relevante psychische oder körperliche Probleme hatten [M04]. Untersucht wurden vollständige Akzeptanz- und Commitment-Therapien mit verschiedenen Bedingungen und Vergleichen. Die Studien prüften weder einen Wertekompass für sich noch die Wirkung dieses einzelnen Arbeitsblatts. Sie zeigen auch nicht, dass ODA eine Therapie bietet. Ein hilfreiches Modell kann eine Wahl unterstützen, ohne die klinischen Belege für eine ganze Behandlung zu übernehmen.","Für den Planungsteil gibt es eigene Befunde zu konkreten Startsignalen und Reaktionen [M11]. „Wenn wir nach dem Abendessen zusammensitzen“ ist leichter zu erkennen als „irgendwann diese Woche“. Die Belege betreffen Zielerreichung, kein Gefühl von Erfüllung. Lass dein Minimum sinnvoll und seinen Preis sichtbar bleiben. Verschiebst du eine nicht dringende Aufgabe, benenne ihren nächsten Zeitpunkt. Der Verzicht verschwindet nicht. Gefährdet die Zeit nötige Versorgung oder Erholung, verkleinere den Schritt, hol Hilfe oder wähle eine andere Gelegenheit."]}],sourceIds:["meaning-act-values","meaning-act-trials","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-3",courseId:"meaning",locale:"de",title:"Deine Wahl darf sich trotzdem schwer anfühlen",goal:"Handle aus einem Grund, hinter dem du stehst. Achte dabei auf Verantwortung und Grenzen.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Du hast etwas Wichtiges gewählt und fühlst dich trotzdem schuldig? Dieses Gefühl entscheidet nicht, ob die Wahl deine ist.",reason:{id:"meaning-3-reason",label:"Hinter welchem Grund stehst du? Was musst du dabei schützen?",kind:"text",maxLength:160,optional:!0,suggestions:["Für geliebte Menschen sorgen","Finanzielle Verpflichtungen einhalten","Ein freiwilliges Vorhaben wählen"]},why:{id:"meaning-3-why",label:"Hinter welchem Grund stehst du? Was musst du dabei schützen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Eine Aufgabe, die du aus deiner Familie kennst, kann dir selbst wichtig werden. Die Motivationsforschung unterscheidet zwischen Gründen, hinter denen du stehst, und Handeln unter Druck. Einen schnellen Echtheitstest liefert sie nicht. Schuldgefühle, Müdigkeit oder Freude sagen etwas über dein Erleben. Sie entscheiden nicht darüber, welcher Wert zu dir gehört.","Schau auf dieselbe Richtung, die du bisher ausprobiert hast. Benenne einen Grund, hinter dem du noch stehst, und eine Grenze, die du beachten musst. Behalte notwendige Verpflichtungen. Ändere eine freiwillige Wahl mit geringen Kosten und tu den nützlichen Schritt. Gemischte Beweggründe sind erlaubt. Du brauchst vorher keine vollkommene Gewissheit."],example:{title:"Thomas bleibt bei seinem eigenen Grund",text:"Am Donnerstag am Küchentisch fühlt sich Thomas schuldig, weil er einen freiwilligen Austausch mit Kollegen absagt. Zeit mit seiner Tochter bleibt ihm wichtig. Seine notwendige Arbeitsschicht behält er. In ihren zwei Minuten fragt er nach ihrem Modell und hört zu. Er notiert das Gespräch und sein Unbehagen. Sein Grund blieb selbst gewählt, obwohl das Schuldgefühl blieb."}},move:{invitation:"Probiere deinen bestehenden kleinen Schritt aus einem Grund, hinter dem du stehst.",instructions:["Behalte nötige Verpflichtungen. Benenne, auf welche freiwillige Sache du dafür verzichtest.","Setze den Schritt um, ohne ein eindeutiges Gefühl zu verlangen."],prompts:[],suggestions:{action:["Aus einem selbst gewählten Grund fragen und zuhören","Freiwillig einen Projektbeitrag leisten","Eine Einladung absagen, um dafür Zeit zu haben"],minimum:["Einer Antwort zuhören","Einen nützlichen Satz verfassen","Klar sagen, wann ich verfügbar bin"],cue:["Wenn wir nach dem Abendessen zusammensitzen","In meiner freiwilligen Projektzeit","Wenn die freiwillige Einladung kommt"],place:["Am Küchentisch","An meinem gewohnten Arbeitsplatz","In einem sicheren Nachrichtenverlauf"],minutes:[2,5],fallback:["Pflichten behalten, diesen Schritt verkleinern","Ein anderes freiwilliges Vorhaben wählen, das weniger kostet","Unterstützung für die Einschränkung suchen"],observation:["Meine Wahl trotz gemischter Gefühle","Der Grund, hinter dem ich weiter stehe","Die Verpflichtung, die ich geschützt habe"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Aus einem selbst gewählten Grund fragen und zuhören",minimum:"Einer Antwort zuhören",minutes:2,cueHint:"Wenn wir nach dem Abendessen zusammensitzen",placeHint:"Am Küchentisch",obstacleHint:"Ich spüre Druck. Manche Verpflichtungen kann ich nicht abgeben.",fallbackHint:"Pflichten behalten, diesen Schritt verkleinern",observationHint:"Meine Wahl trotz gemischter Gefühle"},stopRule:"Vermeide unumkehrbare Änderungen. Schütze nötiges Einkommen, Versorgung, Sicherheit und Unterstützung.",accessibleAlternative:"Wähle privat oder mit Hilfe. Setze eine Grenze schriftlich, wenn das sicher ist, oder hol Unterstützung."},result:{question:"Hast du deinen gewählten Schritt umgesetzt?",observationPrompt:"Was hast du gewählt? Welche Verantwortung hast du geschützt?"},judgment:{primary:{id:"meaning-3-elective-cost-decision",scenario:"Thomas sind sein Einkommen und das Familiengespräch heute wichtig. Der berufliche Austausch findet morgen mit denselben Kontakten erneut statt. Heute fernzubleiben betrifft keine bezahlte Schicht. Trotzdem drängt ihn sein Schuldgefühl, jedes Treffen mitzunehmen.",question:"Welche Wahl prüft seinen Grund mit überschaubaren Kosten?",options:[{id:"meaning-3-attend-and-reschedule",text:"Heute am Austausch teilnehmen und das Familiengespräch nach der nächsten Schicht planen, damit beide Vorhaben erhalten bleiben.",feedback:"Verschieben kann zwei wichtige Vorhaben schützen. Hier sind dieselben Kontakte morgen ohne Einkommensverlust erreichbar. Das gewählte Gespräch heute zu verschieben folgt dem Druck. Eine verfügbare Alternative mit geringeren Kosten bleibt ungenutzt."},{id:"endorsed-choice",text:"Die nötige Arbeitsschicht behalten, das freiwillige Treffen heute absagen und die Gesprächszeit nutzen, die ihm wichtig ist.",feedback:"So prüft er seinen eigenen Grund, schützt das Einkommen und behält die Kontaktmöglichkeit morgen. Schuldgefühle können bleiben. Wären die beruflichen Kosten anders, könnte ein anderer Verzicht sinnvoll sein."},{id:"meaning-3-split-evening",text:"Kurz am Austausch teilnehmen und das Familiengespräch verkürzen, damit er bei beiden sichtbar bleibt.",feedback:"Aufteilen kann passen, wenn beide Gelegenheiten selten sind. Hier findet der berufliche Austausch morgen erneut statt. Heute beides zu teilen schützt Sichtbarkeit auf Kosten seiner gewählten Aufmerksamkeit. Nutze stattdessen die andere verfügbare Gelegenheit."}],bestOptionId:"endorsed-choice"}},carry:{takeaway:"Steh hinter deinem Grund, beachte die Kosten und prüfe ihn mit einer kleinen Wahl.",followUp:{questionId:"meaning-3-return",question:"Stehst du nach deiner Wahl noch hinter dem Grund?",observationPrompt:"Hinter welchem Grund stehst du jetzt, auch mit Zweifeln oder Änderungen?",adjustmentPrompt:"Den Grund behalten, ändern oder Unterstützung bei seinen Kosten suchen?"}},goDeeper:{sections:[{heading:"Übernommen heißt nicht unecht",paragraphs:["Ryan und Decis Selbstbestimmungstheorie beschreibt, wie zunächst von außen kommende Beweggründe persönlich wichtig werden können [M05]. Verantwortung in der Familie kann schwierig sein, Beziehungen betreffen und trotzdem deine sein. Freude ist ein möglicher Grund zu handeln. Die Sicherheit eines Menschen ist ein anderer. Das macht nicht jede Verpflichtung unter Druck gesund. Aber Herkunft, Unbehagen oder Anerkennung allein entscheiden nicht, ob ein Grund zu dir gehört. Frag, welche Gründe du heute befürwortest und welcher Druck deine Wahl begrenzt.","„Würde ich es tun, wenn niemand zusieht?“ ist eine freiwillige Reflexionsfrage, kein geprüfter Test. Schuldgefühl beweist keinen fremden Wert. Körperliche Energie beweist keinen echten. Nach dem Warum zu fragen kann beim Nachdenken helfen. Es bescheinigt dir aber nicht deinen einzig wahren Beweggrund. Auch mit gemischten Gründen kannst du bewusst wählen. Schütze nötiges Einkommen und Versorgung, erkenne kulturell geprägte Verpflichtungen an und prüfe einen umkehrbaren freiwilligen Schritt. Für diese Lektion musst du weder Beruf noch Beziehung oder Familienpflichten verändern."]},{heading:"Unterstützung kann Motivation verändern. Ein Arbeitsblatt hat Grenzen.",paragraphs:["Ntoumanis und andere werteten 73 Gesundheitsstudien mit 30.088 Teilnehmenden aus [M06]. Die Programme stützten durchschnittliche Verbesserungen bei selbstbestimmter Motivation und Gesundheitsverhalten. Die Ergebnisse unterschieden sich erheblich. Darunter waren 58 randomisierte und 15 quasi-experimentelle Studien. Diese Befunde betreffen begleitete Gesundheitsprogramme. Sie zeigen weder, dass drei Fragen einen verborgenen wahren Beweggrund aufdecken, noch dass äußere Gründe immer schaden. Auch reproduziert eine kurze ODA-Übung damit nicht die untersuchten Programme.","Auch das ACT-Modell verbindet bewusst gewählte Arten, auf Dauer zu handeln, mit konkreten Schritten [M19]. Hier ist das eine ODA-Anpassung, keine geprüfte kombinierte Behandlung. Lerne beim nächsten Versuch etwas Konkretes: Passte die Wahl zu deiner Verantwortung? Stehst du noch hinter ihrem Grund? Unbehagen darf im Eintrag stehen bleiben. Bei Zwang oder Gefahr haben Schutz und Unterstützung Vorrang vor Versuchen, sich anzupassen. Du kannst die Richtung ändern, für dich behalten oder pausieren. Du musst dich dafür nicht erklären."]}],sourceIds:["meaning-sdt","meaning-sdt-interventions","meaning-act-values"]}},{schemaVersion:2,revision:2,id:"meaning-4",courseId:"meaning",locale:"de",title:"Schwere Zeiten brauchen keinen schönen Sinn",goal:"Schütze deine Richtung mit einer praktischen Bitte, einer Grenze oder einem fürsorglichen Schritt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Du versuchst, diesem Schmerz einen Sinn zu geben? Schau zuerst, was helfen kann. Die Sinnfrage darf warten.",reason:{id:"meaning-4-reason",label:"Welche praktische Änderung macht diese Richtung auf Dauer machbar?",kind:"text",maxLength:160,optional:!0,suggestions:["Eine Betreuungsaufgabe teilen","Nötige Erholung schützen","Um fachliche Unterstützung bitten"]},why:{id:"meaning-4-why",label:"Welche praktische Änderung macht diese Richtung auf Dauer machbar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ein Ereignis lässt sich vielleicht nicht ändern. Heutige Abläufe können trotzdem veränderbar sein. Eine Krankheit verdient Versorgung und Abklärung. Sie gehört nicht automatisch in die Spalte „Da lässt sich nichts machen“. Frankls Gedanke einer Haltung zu unvermeidbarem Leid ist eine philosophische Möglichkeit. Du musst im Schmerz kein Geschenk finden.","Komm zu deinem Versuch zurück. Wird sein Schritt unter der Belastung auf Dauer zu viel, organisiere passende Unterstützung dafür. Bitte um Hilfe bei einer praktischen Aufgabe, setze eine sichere Grenze oder schütze nötige Erholung. Auch das kann derselben Richtung dienen. Halte die tatsächliche Bitte oder Änderung fest. Du musst dabei keinen Sinn empfinden."],example:{title:"Thomas teilt die Betreuung auf",text:"Am Freitag ist Thomas erschöpft, nachdem er die Termine seines Vaters organisiert hat. Er will weiter für ihn sorgen, ohne jeden Abend zu verlieren. Am Küchentisch bittet er seinen Bruder per Nachricht, am Samstag die Fahrt zu übernehmen. Bis zur Schlafenszeit kommt keine Antwort. Thomas hält die Bitte fest. Die Traurigkeit bleibt. Er macht daraus keine Lebenslektion."}},move:{invitation:"Behalte die Richtung. Ändere eine Belastung, bei der Hilfe möglich ist.",instructions:["Prüfe eine praktische Änderung, bevor du an deiner Haltung arbeitest.","Äußere eine konkrete Bitte oder tu etwas Sicheres zu deinem Schutz."],prompts:[],suggestions:{action:["Hilfe bei einer Betreuungsaufgabe erbitten","Sicher begrenzen, wann ich verfügbar bin","Fachliche Unterstützung anfragen"],minimum:["Eine konkrete Bitte um Hilfe senden","Eine klare Grenze aussprechen","Eine Unterstützungsstelle kontaktieren"],cue:["Nach dem Abendessen vor der Terminplanung","Wenn die nächste Bitte kommt","Bei meiner gewählten Gelegenheit für Unterstützung"],place:["Am Küchentisch","In einem sicheren Nachrichtenverlauf","An meinem zugänglichen privaten Ort"],minutes:[2,5],fallback:["Eine andere geeignete Person um Hilfe bitten","Die Grenze privat halten und Hilfe holen","Einen zugänglichen Weg zu Unterstützung wählen"],observation:["Meine Bitte und welche Antwort tatsächlich kam","Der Ablauf, den ich verändert habe","Ob ich die Unterstützungsstelle kontaktiert habe"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Hilfe bei einer Betreuungsaufgabe erbitten",minimum:"Eine konkrete Bitte um Hilfe senden",minutes:2,cueHint:"Nach dem Abendessen vor der Terminplanung",placeHint:"Am Küchentisch",obstacleHint:"Die erste Person kann nicht helfen oder der Kontakt ist unsicher.",fallbackHint:"Eine andere geeignete Person um Hilfe bitten",observationHint:"Meine Bitte und welche Antwort tatsächlich kam"},stopRule:"In den USA: 988 anrufen oder anschreiben. Anderswo örtliche Krisenhilfe nutzen. Bei unmittelbarer Gefahr den örtlichen Notruf wählen.",accessibleAlternative:"Nutze Hilfe für die Bitte oder wähle Erholung. Such frühzeitig fachliche Unterstützung, wenn Hoffnungslosigkeit anhält oder dein Alltag leidet."},result:{question:"Hast du deinen gewählten praktischen Schritt getan?",observationPrompt:"Worum hast du gebeten oder was geändert? Auch keine Antwort zählt."},judgment:{primary:{id:"meaning-4-transport-constraint-decision",scenario:"Die Fahrt zum Arzt am Samstag erschöpft Thomas. Sein Bruder hat angeboten zu fahren, braucht aber heute Abend die Zusage. Der Besuch kann kürzer sein, die Fahrt ist nötig. Der kostenlose örtliche Fahrdienst hat samstags keinen freien Platz.",question:"Welche Regelung hilft bei der jetzigen Belastung?",options:[{id:"meaning-4-shorten-visits",text:"Den Besuch am Samstag verkürzen und selbst fahren, um ohne weitere Absprachen die Belastung zu senken.",feedback:"Kürzere Besuche können Kraft schützen und trotzdem helfen. Die nötige Fahrt, die ihn erschöpft, bleibt aber unverändert. Bestätige das verfügbare Fahrangebot und wähle dann eine Besuchsdauer, die auf Dauer passt."},{id:"meaning-4-community-route",text:"Beim Fahrdienst nach einem frei werdenden Platz fragen und erst danach dem Bruder zusagen.",feedback:"Der Fahrdienst könnte später hilfreich sein. Für Samstag gibt es keinen zugesagten Platz. Der Bruder braucht heute Abend eine Antwort. Sichere die verfügbare Hilfe, statt auf einen möglicherweise frei werdenden Platz beim Fahrdienst zu warten."},{id:"share-task",text:"Den Bruder bitten, die Fahrt zu übernehmen. Dann eine Besuchsdauer wählen, die er durchhalten kann.",feedback:"So nutzt er das verfügbare Angebot für die veränderbare Belastung und sichert die medizinisch nötige Fahrt. Die Bitte ist erledigt, bevor eine Zusage kommt. Halte eine unbeantwortete Bitte genau so fest."}],bestOptionId:"share-task"}},carry:{takeaway:"Ändere Hilfe und Abläufe, bevor du eine bessere Haltung von dir verlangst.",followUp:{questionId:"meaning-4-return",question:"Welche Hilfe oder praktische Änderung folgte auf deine Bitte?",observationPrompt:"Welche Antwort oder Änderung gab es? Auch keine Antwort zählt.",adjustmentPrompt:"Welche Hilfe, Grenze oder Erholung passt zur verbleibenden Belastung?"}},goDeeper:{sections:[{heading:"Vergangene Tatsachen und heutige Möglichkeiten",paragraphs:["Frankls Ansatz enthält eine mögliche Haltung zu Leid, das sich wirklich nicht vermeiden lässt [M17]. Das ist philosophische Orientierung. Es belegt nicht, dass Haltung Krankheiten heilt oder Trauma nützlich macht. Ein Tod oder vergangenes Ereignis lässt sich nicht rückgängig machen. Heutige Symptome, Behandlungen, soziale Unterstützung und Alltagsabläufe können trotzdem veränderbar sein. Ordne weder eine Diagnose noch die Schädigung durch andere oder fehlende Hilfe als unveränderbar ein, bevor du Unterstützung in Betracht gezogen hast.","Das ACT-Modell bietet gewählte Arten des Handelns auch bei schwierigen Gefühlen an [M19]. Es verlangt weder, die Gefühle zu beseitigen, noch in vermeidbarer Gefahr zu bleiben. Dein Versuch kann Fürsorge als Richtung behalten und statt eines weiteren Besuchs eine Bitte um geteilte Fahrten vorsehen. Erholung, eine Grenze oder Informationen können der passende Schritt sein. Das sind Entscheidungen im jeweiligen Kontext, kein Beweis für eine edle Haltung. Die Sinnfrage darf offen bleiben. ODA schuldest du niemals eine Schilderung deines Leids."]},{heading:"Unterstützung muss nicht auf einen Lebenssinn warten",paragraphs:["Das National Institute of Mental Health beschreibt Symptome einer Depression sowie fachliche Abklärung und Behandlungsmöglichkeiten [M20]. Anhaltende Hoffnungslosigkeit, Niedergeschlagenheit, Interessenverlust oder Schwierigkeiten im Alltag verdienen Unterstützung. Fehlender Sinn allein ist keine Diagnose. Ein Kurs kann sie nicht stellen. Du kannst Hilfe suchen, bevor Symptome eine bestimmte Zeit lang bestehen. Warte weder auf das Kursende noch auf eine Antwort zu deinen Werten, bevor du ärztliche oder psychotherapeutische Unterstützung kontaktierst.","In den USA kannst du bei Suizidgedanken oder einer seelischen Krise 988 anrufen oder anschreiben. Bei unmittelbarer Gefahr nutze den Notruf. Anderswo nutze örtliche Krisen- oder Notfallhilfe. In einer Krise ist menschliche Hilfe der passende nächste Schritt. Eine weitere Reflexionsübung reicht dafür nicht. Außerhalb einer Krise darf deine Bitte konkret und klein bleiben: eine Betreuungsaufgabe, Zeit zur Erholung oder ein Termin. Keine Antwort ist ebenfalls eine sachliche Beobachtung. Ist der erste Weg nicht verfügbar, such einen anderen passenden Weg. Das Hindernis bedeutet nicht, dass deine Sinnsuche gescheitert ist."]}],sourceIds:["meaning-frankl","meaning-act-values","meaning-support"]}},{schemaVersion:2,revision:2,id:"meaning-5",courseId:"meaning",locale:"de",title:"Zukunft ausgemalt? Setze heute einen Teil davon um",goal:"Nutze eine bescheidene Zukunftsszene, um einen konkreten Schritt für deine bestehende Richtung zu wählen.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Im Kopf hast du deine Zukunft schon geplant. Was tust du diese Woche konkret dafür?",reason:{id:"meaning-5-reason",label:"Was muss sich diese Woche ändern, damit diese Zukunft passt?",kind:"text",maxLength:160,optional:!0,suggestions:["Zeit füreinander nutzen","Etwas Nützliches herstellen","Mein Budget und meine Kraft achten"]},why:{id:"meaning-5-why",label:"Was muss sich diese Woche ändern, damit diese Zukunft passt?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Für das Schreiben über die Zukunft gibt es klarere Forschungsbelege zu Optimismus und positiven Gefühlen als zu weniger Depression oder negativen Gefühlen. Die vorgestellte Zukunft wird dadurch nicht nachweislich Wirklichkeit. Eine kurze Szene kann deinen Versuch vorbereiten. Sie ist kein Beleg, dass du bereits gehandelt hast.","Stell dir einen normalen Tag in naher Zukunft vor, wenn es hilft. Bleib bei deiner bestehenden Richtung. Wähle einen nächsten konkreten Schritt: ein echtes Gespräch, einen nützlichen Satz oder eine konkrete Bitte. Beachte das Hindernis und deine Möglichkeiten. Setze dann diesen Teil um. Lass Zukunftsbilder weg, wenn sie nicht helfen. Du kannst den Schritt auch direkt wählen."],example:{title:"Ein gewöhnlicher Dienstag für Thomas",text:"Beim Samstagsfrühstück stellt sich Thomas einen Dienstag vor: Die Betreuung ist aufgeteilt und er hilft zu Hause. Die Szene ist Vorbereitung. Einen Teil setzt er um. Er schreibt eine klare Beschriftung für das Schulmodell seiner Tochter. Am Küchentisch wird die Beschriftung fertig. Am übrigen Modell gibt es noch Arbeit."}},move:{invitation:"Setze heute einen Teil deines Zukunftsbildes mit dem Schritt um, den du bereits gewählt hast.",instructions:["Nutze bei Bedarf eine kurze Szene. Das ist Vorbereitung.","Benenne ein echtes Hindernis und setze dann einen passenden Teil um."],prompts:[],suggestions:{action:["Einen nützlichen Satz fürs Projekt verfassen","Eine nützliche Projektskizze zeichnen","Eine passende Bitte um Rückmeldung senden"],minimum:["Einen brauchbaren Satz verfassen","Eine brauchbare Skizze zeichnen","Mit einer konkreten Frage um Rückmeldung bitten"],cue:["Wenn ich mein Projekt öffne","Wenn das Projekt eine Skizze braucht","In meiner freigehaltenen Arbeitszeit"],place:["An meinem gewohnten Arbeitsplatz","Am Küchentisch","In einem sicheren Nachrichtenverlauf"],minutes:[2,5],fallback:["Einen kleineren passenden Beitrag wählen","Stattdessen mit Worten beschreiben","Um Hilfe beim Zugang bitten"],observation:["Mein tatsächlich geleisteter Beitrag","Was das Hindernis geändert hat","Meine Bitte und welche Antwort tatsächlich kam"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Einen nützlichen Satz fürs Projekt verfassen",minimum:"Einen brauchbaren Satz verfassen",minutes:2,cueHint:"Wenn ich mein Projekt öffne",placeHint:"An meinem gewohnten Arbeitsplatz",obstacleHint:"Mein Zukunftsbild verlangt mehr Mittel, als ich habe.",fallbackHint:"Einen kleineren passenden Beitrag wählen",observationHint:"Mein tatsächlich geleisteter Beitrag"},stopRule:"Wähle ein bescheidenes, sicheres Zukunftsbild. Lass Bilder weg, wenn die Belastung zunimmt. Vermeide kostspielige Verpflichtungen.",accessibleAlternative:"Wähle den Schritt direkt, nutze Worte statt Bilder oder leiste einen Beitrag mit Unterstützung."},result:{question:"Hast du deinen gewählten konkreten Schritt umgesetzt?",observationPrompt:"Was war nach deinem Versuch tatsächlich da oder passiert?"},judgment:{primary:{id:"meaning-5-feedback-opening-decision",scenario:"Eine Designerin hat eine fertige Arbeitsprobe. Heute Abend hat ein Kollege Zeit für Rückmeldung. Ihr Zukunftswunsch ist gemeinsame Arbeit. Bessere Ausstattung kann sie nächste Woche leihen. Für diese Arbeitsprobe braucht sie die aber nicht.",question:"Welcher Schritt prüft diese Richtung mit den vorhandenen Mitteln?",options:[{id:"meaning-5-prepare-presentation",text:"Heute die Präsentation der Arbeitsprobe verbessern und beim nächsten freien Termin des Kollegen um Rückmeldung bitten.",feedback:"Eine bessere Präsentation kann eine Arbeitsprobe verständlicher machen. Diese ist fertig, und der Kollege hat heute Abend Zeit. Schick jetzt eine konkrete Frage. Entscheide anhand der Antwort, ob die Präsentation Arbeit braucht."},{id:"share-sample",text:"Das Budget schützen und die vorhandene Arbeitsprobe mit einer konkreten Frage zur Rückmeldung schicken.",feedback:"So prüft sie ein passendes Verhalten mit vorhandenen Mitteln. Zukunftsschreiben und Zielerreichung sind verschiedene Ergebnisse. Auch eine unvollkommene Antwort gibt Hinweise für den nächsten Versuch."},{id:"meaning-5-borrow-equipment",text:"Auf die geliehene Ausstattung nächste Woche warten und erst eine bessere Arbeitsprobe erstellen, bevor sie Rückmeldung anfragt.",feedback:"Leihen schützt das Budget, wenn Ausstattung nötig ist. Für diese Arbeitsprobe braucht sie keine zusätzliche Ausstattung. Der Kollege hat jetzt Zeit. Prüfe gemeinsame Arbeit mit der vorhandenen Arbeitsprobe, bevor du zusätzliche Anforderungen stellst."}],bestOptionId:"share-sample"}},carry:{takeaway:"Eine Zukunftsszene ist Vorbereitung. Setze heute einen passenden Teil davon um.",followUp:{questionId:"meaning-5-return",question:"Hat dein Schritt die Zukunftsszene mit dieser Woche verbunden?",observationPrompt:"Was hast du konkret getan oder erstellt? Wie diente es deiner Richtung?",adjustmentPrompt:"Welche Mittel oder Hindernisse solltest du beim nächsten Beitrag berücksichtigen?"}},goDeeper:{sections:[{heading:"Was Schreiben über die Zukunft tatsächlich gezeigt hat",paragraphs:["Carrillo und andere fassten 29 Studien mit 2.909 Teilnehmenden zusammen [M09]. Die Ergebnisse stützten durchschnittliche Verbesserungen bei Wohlbefinden, Optimismus und positiven Gefühlen. Weniger negative Gefühle oder depressive Symptome wurden nicht nachgewiesen. Die Konfidenzintervalle schlossen null ein. Nur drei Studien erfassten Depression. Ein positiv wirkender Durchschnittswert beseitigt die Unsicherheit einer Schätzung nicht. Die Studien erfassten meist kurzfristige Ergebnisse und nutzten unterschiedliche Schreibabläufe. Sie belegten weder mehr Sinn noch tatsächlich erreichte Zukunftsziele.","In Kings ursprünglicher Studie wurden 81 Studierende zufällig vier Schreibbedingungen zugeordnet. Die Zukunftsaufgabe sah an vier aufeinanderfolgenden Tagen jeweils 20 Minuten Schreiben vor [M10]. Die kurze Szene hier liegt in naher Zukunft und bezieht sich auf Werte. Sie verändert Umfang und Zweck. Das ist eine ODA-Anpassung, nicht der ursprüngliche Ablauf. Freiwilliges längeres Schreiben braucht eigene Zeit. Du musst weder ein ideales Leben in fünf Jahren entwerfen noch dich daran messen. Eine gewöhnliche Möglichkeit kann reichen, um den nächsten praktischen Schritt zu wählen."]},{heading:"Stell der Zukunft ein heutiges Hindernis gegenüber",paragraphs:["Mentales Kontrastieren mit Wenn-dann-Plänen verbindet einen machbaren Wunsch, das gewünschte Ergebnis, ein heutiges Hindernis und eine passende Reaktion. Wang und andere werteten 24 unabhängige Studien aus 21 Artikeln mit 15.907 Teilnehmenden aus [M13]. Der durchschnittliche Effekt auf die Zielerreichung war mäßig: g = 0,336, mit einem 95%-Konfidenzintervall von 0,229 bis 0,443. Eine Anpassung für Publikationsverzerrungen ergab einen kleineren Schätzwert. Unterschiedliche Formate und Studienqualität begrenzen die Sicherheit. Eine allgemein nachgewiesene Sitzungsdauer gibt es nicht.","Dieser Kurs verbindet eine Zukunftsszene mit deiner bestehenden Richtung und einem konkreten Schritt. Diese Kombination wurde nicht geprüft. Fehlende Mittel, Betreuungsaufgaben oder ein unsicheres Umfeld sind echte Grenzen. Sie sind keine innere Schwäche. Eine praktische Antwort kann ein kleineres passendes Arbeitsergebnis, eine Bitte um Hilfe oder eine andere Gelegenheit sein. Halte das tatsächliche Arbeitsergebnis oder Gespräch getrennt von der Szene fest. Macht die Zukunftsvorstellung Druck oder belastet dich, lass sie weg. Wähle deinen Schritt dann direkt."]}],sourceIds:["meaning-carrillo","meaning-best-possible-self","meaning-mental-contrasting"]}},{schemaVersion:2,revision:2,id:"meaning-6",courseId:"meaning",locale:"de",title:"Wieder ein Plan geplatzt? Behalte, was klappt",goal:"Nutze deine Einträge: Wiederhole, ändere oder beende nächste Woche einen Versuch für das, was dir wichtig ist.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Wieder ein Plan geplatzt? Entscheide anhand deiner tatsächlichen Versuche, was als Nächstes kommt.",reason:{id:"meaning-6-reason",label:"Welcher Schritt verdient einen weiteren Platz in deiner Woche?",kind:"text",maxLength:160,optional:!0,suggestions:["Einen nützlichen kleinen Schritt behalten","Ein Startsignal ändern, das nicht funktioniert hat","Eine tragfähige Richtung schützen"]},why:{id:"meaning-6-why",label:"Welcher Schritt verdient einen weiteren Platz in deiner Woche?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Planen ist noch kein Handeln. Pläne mit Startsignal und das Beobachten von Fortschritten unterstützen im Durchschnitt die Zielerreichung. Beides belegt nicht, dass tägliches Handeln mehr Sinn schafft. Trenne die Tatsachen deines Versuchs vom Gefühl dabei.","Prüfe deine Einträge zur selben Richtung. Welche Gelegenheit gab es? Welches Minimum erfüllte seinen Zweck? Wähle eine Sache, die du nächste Woche wiederholst oder änderst. Behalte den nützlichen Schritt. Lass zusätzliche Rituale weg. Eine verpasste Gelegenheit liefert Hinweise. Sie ist weder eine Frist für eine Gewohnheit noch ein Urteil über deine Werte. Unterstützung, Erholung und das Beenden eines schädlichen Plans bleiben möglich."],example:{title:"Thomas plant anhand seiner Einträge",text:"Am Sonntag sieht Thomas am Küchentisch in seinen Einträgen zwei Gespräche, eine ausgebliebene Gelegenheit und eine unbeantwortete Bitte um Hilfe. Zwei Minuten nach dem Abendessen klappten besser als spät am Abend. Er fragt seine Tochter wieder nach dem Modell und hört zu. Für nächste Woche behält er dieses Startsignal. Werden die Besuche zu viel, bittet er erneut um Unterstützung."}},move:{invitation:"Nutze deine Einträge. Behalte einen nützlichen Schritt für die nächste Woche.",instructions:["Vergleiche die tatsächlichen Gelegenheiten und die ausprobierten Mindestschritte.","Ändere eine Bedingung und starte dann den nächsten Versuch."],prompts:[],suggestions:{action:["Wieder kurz fragen und zuhören","Meinen nützlichen Projektbeitrag wiederholen","Um die laut Rückblick nötige Hilfe bitten"],minimum:["Einer Antwort zuhören","Einen brauchbaren Satz verfassen","Eine konkrete Bitte um Unterstützung senden"],cue:["Wenn wir nach dem Abendessen zusammensitzen","Bei meinem erprobten Projekt-Startsignal","Vor der nächsten Betreuungsabsprache"],place:["Am Küchentisch","An meinem gewohnten Arbeitsplatz","In einem sicheren Nachrichtenverlauf"],minutes:[2,5],fallback:["Meine erprobte kleinere Fassung nutzen","Eine andere realistische Gelegenheit wählen","Unterstützung holen oder den Plan pausieren"],observation:["Mein Schritt und ob das Startsignal kam","Was die geänderte Bedingung ermöglicht hat","Ob das Minimum weiter meiner Richtung diente"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Wieder kurz fragen und zuhören",minimum:"Einer Antwort zuhören",minutes:2,cueHint:"Wenn wir nach dem Abendessen zusammensitzen",placeHint:"Am Küchentisch",obstacleHint:"Die bisherige Zeit passt nicht mehr zu meiner Verantwortung.",fallbackHint:"Meine erprobte kleinere Fassung nutzen",observationHint:"Mein Schritt und ob das Startsignal kam"},stopRule:"Ändere oder beende Pläne, die Sicherheit, Versorgung oder nötiger Erholung widersprechen.",accessibleAlternative:"Behalte einen zugänglichen Schritt, bitte um Unterstützung oder wähle Erholung. Ein neues Ritual ist dafür nicht nötig."},result:{question:"Hast du den nächsten kleinen Schritt umgesetzt?",observationPrompt:"Was hast du tatsächlich getan? Ist das gewählte Startsignal eingetreten?"},judgment:{primary:{id:"meaning-6-tested-opening-decision",scenario:"Thomas' spätes Zeitfenster fiel zweimal aus, weil Besuche länger dauerten. Beim Abendessen gab es zwei kurze Gespräche. Am Wochenende ist freie Zeit ungewiss. Er möchte nächste Woche Kontakt und kann wieder die Gelegenheit beim Abendessen nutzen.",question:"Welcher Plan für nächste Woche nutzt diese Einträge am besten?",options:[{id:"meaning-6-earlier-night",text:"Das Abendgespräch dreißig Minuten vorziehen, um eine längere ungestörte Unterhaltung beizubehalten.",feedback:"Früher anzufangen könnte ein längeres Gespräch ermöglichen. Die Einträge zeigen aber weiterhin lange Besuche. Sie belegen nicht, dass die Verschiebung diese umgeht. Prüfe die Gelegenheit beim Abendessen, die schon Kontakt ermöglicht hat."},{id:"meaning-6-weekend-conversation",text:"Ein längeres Gespräch am Wochenende reservieren, damit die Besuche unter der Woche dem geplanten Kontakt nicht mehr im Weg stehen.",feedback:"Ein Wochenendgespräch kann wertvoll sein, wenn beide eine Zeit vereinbaren. Hier ist freie Zeit ungewiss. Behalte nächste Woche das erprobte Minimum beim Abendessen. Vereinbare ein längeres Gespräch, wenn es wirklich eine Gelegenheit gibt."},{id:"tested-cue",text:"Bei der Beziehung bleiben, das Minimum beim Abendessen nutzen und den nächsten Versuch festhalten, bevor er etwas Weiteres ändert.",feedback:"So wiederholt er eine Gelegenheit, die den gewählten Schritt ermöglicht hat. Ein weiteres Gespräch ist nicht garantiert. Notiere Startsignal und Verlauf. Entscheide dann, ob mehr Unterstützung oder eine Änderung nötig ist."}],bestOptionId:"tested-cue"}},carry:{takeaway:"Behalte eine Richtung, einen nützlichen Schritt und Einträge, die den nächsten Versuch verbessern.",followUp:{questionId:"meaning-6-return",question:"Hat die anhand deiner Einträge gewählte Bedingung beim nächsten Schritt geholfen?",observationPrompt:"Kam das Startsignal? Was hat diese Bedingung ermöglicht?",adjustmentPrompt:"Die Bedingung wieder nutzen, ändern, Unterstützung holen oder aufhören?"}},goDeeper:{sections:[{heading:"Planen und Beobachten beantworten Fragen zum Handeln",paragraphs:["Gollwitzer und Sheeran fassten 94 unabhängige Untersuchungen mit 8.461 Teilnehmenden zusammen [M11]. Konkrete Pläne, die Situation und Reaktion verbinden, verbesserten im Durchschnitt die Zielerreichung. Designs und Umgebungen unterschieden sich. Harkin und andere werteten 138 randomisierte Studien zum Beobachten von Fortschritten aus [M14]. Der zusammengefasste Schätzwert für Zielerreichung war d = 0,40, mit einem 95%-Konfidenzintervall von 0,32 bis 0,48. Kleine Studien zeigten eine Asymmetrie. Eine Sensitivitätsanalyse schätzte d = 0,19. Das sind Befunde zur Zielerreichung, kein Versprechen von Erfüllung.","ODAs Zusammenfassung und Rückblick am nächsten Tag wurden durch diese Auswertungen nicht bestätigt. Sie sollen einen konkreten Plan mit einem tatsächlichen Versuch vergleichen und eine passendere Wahl ermöglichen. Öffentliches Protokollieren ist unnötig. Behalte sensible Angaben außerhalb von ODA, wenn du möchtest. Ein künftiger Plan bleibt geplant. Ohne Bericht bleibt der Ausgang unbekannt. Du kannst ein hilfreiches Minimum wiederholen, ohne es zu vergrößern. Eine praktische Bitte um Unterstützung oder geplante Erholung kann derselben Richtung besser dienen als eine weitere anstrengende Leistung."]},{heading:"Eine Gewohnheitsschätzung ist keine Frist",paragraphs:["Lally und andere begleiteten 96 Teilnehmende in einer 84-tägigen Beobachtungsstudie [M15]. Die Menschen wählten Ess-, Trink- oder Bewegungsverhalten mit täglichen Startsignalen. Im Modell entwickelte sich automatisches Handeln sehr unterschiedlich schnell. Der bekannte Median von 66 Tagen und die Spanne von 18–254 Tagen sind Modellschätzungen. Längere Schätzungen reichen über die Beobachtung hinaus. Sie sind weder Fristen für deinen Schritt noch Belege dafür, dass Werte automatisch werden oder mehrere verpasste Tage folgenlos bleiben. Eine einzelne verpasste Gelegenheit hatte in dieser Studie wenig messbaren Einfluss.","Dein Versuch verbindet einen Schritt nach deinen Werten, der nichts mit Essen zu tun hat, mit einem Rückblick am Folgetag. Das ist eine Anpassung, nicht der Studienablauf. Festige, was deine Einträge stützen: ein machbares Startsignal, ein nützliches Minimum und eine Antwort auf das tatsächliche Hindernis. Lass eine Übung weg, die nicht geholfen hat. Hole eine unterbrochene Woche nicht nach, indem du jede Anforderung verdoppelst. Wähle die nächste machbare Gelegenheit. Bitte bei Bedarf um Unterstützung. Wenn du den Plan änderst, lass die bisherigen Einträge unverändert."]}],sourceIds:["meaning-planning","meaning-monitoring","meaning-habits"]}}],d=[{id:"meaning-1",practice:["Wähle einen Beitrag oder eine Beziehung. Über Leid nachzudenken bleibt freiwillig.","Benenne einen nützlichen Schritt und eine sichere Gelegenheit.","Setze den gewählten Schritt um und halte fest, was passiert ist."],correct:1,photo:{id:"1469474968028-56623f02e42e",alt:"Eine einzelne Person auf einem Felsen über einem nebligen Tal"}},{id:"meaning-2",practice:["Bleib bei deiner gewählten Richtung und deinem Schritt.","Halte eine machbare Zeit frei und benenne, was nicht Dringendes dafür warten darf.","Setze das nützliche Minimum um und halte fest, was wartete."],correct:2,photo:{id:"1470071459604-3b5ec3a7fe05",alt:"Wolken ziehen über grüne Klippen und ein Tal"}},{id:"meaning-3",practice:["Benenne einen Grund, hinter dem du stehst. Gemischte Beweggründe sind erlaubt.","Schütze notwendige Pflichten. Wähle einen umkehrbaren Verzicht bei etwas Freiwilligem.","Setze den Schritt um und halte deine Wahl fest, ohne Schuldgefühle zu bewerten."],correct:0,photo:{id:"1447752875215-b2761acb3c5d",alt:"Ein Holzsteg durch einen grünen Wald"}},{id:"meaning-4",practice:["Prüfe, welche praktische Hilfe oder welcher Schutz möglich ist.","Wähle eine konkrete Bitte, eine sichere Grenze oder nötige Erholung.","Setze den gewählten Schritt um, ohne Sinn oder eine gute Seite des Leids zu verlangen."],correct:2,photo:{id:"1519681393784-d120267933ba",alt:"Sterne über verschneiten Bergen bei Nacht"}},{id:"meaning-5",practice:["Stell dir freiwillig eine bescheidene Szene in naher Zukunft vor. Das ist Vorbereitung, nicht der ursprüngliche Schreibablauf.","Benenne ein echtes Hindernis und eine machbare Reaktion.","Setze einen passenden Teil um und halte ihn getrennt von der Szene fest."],correct:1,photo:{id:"1501785888041-af3ef285b470",alt:"Ein ruhiger See, umgeben von Bergen"}},{id:"meaning-6",practice:["Vergleiche die tatsächlichen Versuche für deine bestehende Richtung.","Wähle eine Bedingung, die du nächste Woche wiederholst oder änderst.","Probiere das nützliche Minimum. Halte Startsignal und Schritt fest."],correct:1,photo:{id:"1472214103451-9374bd1c798e",alt:"Eine grüne Wiese mit Bäumen im sanften Licht"}}],l={id:"meaning",title:"Immer beschäftigt, ohne Richtung? Gib dem Wichtigen Platz",subtitle:"6 Lektionen: Eine wichtige Richtung wird zu echten Schritten, ehrlichen Einträgen und einer machbaren nächsten Woche.",description:"Wähle etwas, das du beitragen möchtest, oder eine Beziehung, die dir wichtig ist. Probiere einen kleinen Schritt, beachte seinen Preis und passe ihn anhand der Tatsachen an.",scope:"Für Erwachsene, die viel tun, aber keine Richtung spüren, vor einer Entscheidung stehen oder ihren Alltag nach dem gestalten möchten, was ihnen wichtig ist. Der Kurs bietet Wissen und Selbstreflexion, keine Therapie oder Behandlung. Halten Leere oder Hoffnungslosigkeit an oder wird der Alltag schwierig, sprich mit einer ärztlichen oder psychotherapeutischen Fachperson. Du kannst auch früher Unterstützung suchen. Bei Suizidgedanken oder einer seelischen Krise in den USA: 988 anrufen oder anschreiben. Anderswo nutze örtliche Krisenhilfe. Bei unmittelbarer Gefahr nutze den örtlichen Notruf.",outcome:"Ein Versuch, bei dem du nach deinen Werten handelst, mit tatsächlichen Einträgen und einem Plan für nächste Woche, der deine Verantwortung berücksichtigt.",photo:{id:"1500530855697-b586d89ba3ee",alt:"Eine Straße windet sich durch offene Hügel zum Horizont"},lang:"de",lessons:h.map((e,a)=>{const t=d[a],n=e.judgment.primary,r=n.options.find(i=>i.id===n.bestOptionId),s=n.options.filter(i=>i.id!==n.bestOptionId).map(i=>i.text);return s.splice(t.correct,0,r.text),{...t,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,reflection:e.direction.reason.label,question:`${n.scenario} ${n.question}`,options:s,feedback:r.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds}})};export{l as COURSE,h as MEANING_LESSONS_V2,u as SOURCES};
